    g=[['#' if r.random()<p else '.' for _ in range(n)] for _ in range(n)]
    g[0][0]='S'; g[n-1][n-1]='E'
    return [''.join(x) for x in g]
def ref(L):
    h=len(L);w=len(L[0])
    for i in range(h):
        for j in range(w):
            if L[i][j]=='S':s=(i,j)
            if L[i][j]=='E':e=(i,j)
    D={s:0};q=deque([s])
    while q:
        a,b=q.popleft()
        if (a,b)==e:return D[e]
        for x,y in((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
            if 0<=x<h and 0<=y<w and L[x][y]!='#' and (x,y) not in D:
                D[(x,y)]=D[(a,b)]+1;q.append((x,y))
    return -1
